// A module built against this header can be installed on a cube whose firmware predates these two slots, and
// it then reads NULL in them. Guarded like OCT_first_run above rather than left to every game to remember:
// unguarded, the very first save call on such a cube is a jump to address 0, on the player's device, with
// nothing to have warned the developer. ON OLD FIRMWARE BOTH ANSWER OCT_SAVE_UNSUPPORTED, which is negative
// and is not OCT_SAVE_OK, so a game's natural checks -- "did I get my bytes back" and "was it written" --
// both read it as "no save here" without knowing the code exists. Nothing is read, written or zeroed.
#define OCT_save_read(dst, offset, size)        (OCT_APP_IMPORTS.save_read  != NULL ? OCT_APP_IMPORTS.save_read((dst), (offset), (size))  : OCT_SAVE_UNSUPPORTED)
#define OCT_save_write(src, offset, size)       (OCT_APP_IMPORTS.save_write != NULL ? OCT_APP_IMPORTS.save_write((src), (offset), (size)) : OCT_SAVE_UNSUPPORTED)
#define OCT_save_erase()                        (OCT_APP_IMPORTS.save_erase != NULL ? OCT_APP_IMPORTS.save_erase()                        : OCT_SAVE_UNSUPPORTED)
#define OCT_save_sync(offset, size)             (OCT_APP_IMPORTS.save_sync  != NULL ? OCT_APP_IMPORTS.save_sync((offset), (size))          : OCT_SAVE_UNSUPPORTED)

static inline float OCT_lerp(float from, float to, float t) { return from*t + to*(1.0f-t); }

