//OCT_random_local on firmware without the slot. Not `random`: a face-only sparkle drawn from it would advance the
//shared stream on some modules only and split the game. The stream is the same on every module there, which
//decoration can live with.
static inline int OCT_random_local_fallback(int dmin, int dmax)
{
    static uint32_t state = 1;
    return OCT_random_draw(&state, dmin, dmax);
}

