static inline float OCT_TM_sin(int deg) { deg = deg % 360; if (deg < 0) deg += 360; return _OCT_MODULE_SIN[deg]; }
static inline float OCT_TM_cos(int deg) { deg = (deg+90) % 360; if (deg < 0) deg += 360; return _OCT_MODULE_SIN[deg]; }
static inline int   OCT_TM_normalize_angle(int deg) { deg = deg % 360; if (deg < 0) deg += 360; return deg; }

